export const INLINE_COMPONENT_TEMPLATE_SELECTOR="template[acl-component],template[x-acl]";export const getInlineComponentName=e=>{let t=e?.getAttribute?.("acl-component")?.trim()||"",o=e?.getAttribute?.("x-acl")?.trim()||"";if(t&&o&&t.toLowerCase()!==o.toLowerCase())throw TypeError(`[ACL] Inline template markers conflict: acl-component="${t}" and x-acl="${o}".`);return o||t||null};export const containsInlineComponentTemplate=e=>!!(e?.matches?.(INLINE_COMPONENT_TEMPLATE_SELECTOR)||e?.querySelector?.(INLINE_COMPONENT_TEMPLATE_SELECTOR));export const collectInlineComponentTemplates=e=>{let t=[];return e?.matches?.(INLINE_COMPONENT_TEMPLATE_SELECTOR)&&t.push(e),e?.querySelectorAll?.(INLINE_COMPONENT_TEMPLATE_SELECTOR).forEach(e=>t.push(e)),t};